async def act(page):
    # Extract star counts and project names from the current page
    star_data = []

    # Get all links on the page
    all_links = await page.get_by_role('link').all()

    for link in all_links:
        # Check if the link href contains '/starrers'
        href = await link.get_attribute('href')
        if href and '/starrers' in href:
            # Get the star count text
            star_count_text = await link.inner_text()
            try:
                star_count = int(star_count_text)
            except ValueError:
                continue  # Skip if not a valid number

            # Find the project name: get the nearest preceding heading with level 2
            # Use evaluate to find it in the DOM, as Playwright doesn't have a direct method for preceding siblings
            project_name = await link.evaluate('''(link) => {
                // Find the closest main ancestor
                let main = link.closest('main');
                if (!main) return '';
                // Get all h2 elements in main
                let headings = Array.from(main.querySelectorAll('h2'));
                // Find the heading that comes before this link in document order
                let linkIndex = Array.from(main.querySelectorAll('*')).indexOf(link);
                let precedingHeading = null;
                for (let heading of headings) {
                    let headingIndex = Array.from(main.querySelectorAll('*')).indexOf(heading);
                    if (headingIndex < linkIndex) {
                        precedingHeading = heading;
                    } else {
                        break;
                    }
                }
                return precedingHeading ? precedingHeading.innerText.trim() : '';
            }''')

            if project_name:
                star_data.append({
                    'star_count': star_count,
                    'project_name': project_name,
                    'star_link': link
                })

    # Sort by star count descending
    star_data.sort(key=lambda x: x['star_count'], reverse=True)
    top_four = star_data[:4]

    # Star each of the top four projects
    for project in top_four:
        # Click the project link (the heading link) to go to the project page
        project_link = page.get_by_role('heading', level=2, name=project['project_name']).get_by_role('link')
        await project_link.click()
        await page.wait_for_load_state('networkidle')

        # Find and click the star button on the project page
        # Assuming the star button has role 'button' and name 'Star' (case-insensitive)
        star_button = page.get_by_role('button', name='Star', exact=False)
        await star_button.click()
        await page.wait_for_timeout(1000)  # Wait for the action to complete

        # Go back to the projects list
        await page.go_back()
        await page.wait_for_load_state('networkidle')

    # After starring all, no further action needed
    return 'Starred the top four most stared repos.'

